document.addEventListener('click',e=>{if(!e.target.closest('.settings-wrap'))settingsOpen(false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#settings-panel').hidden)settingsOpen(false,true);});
document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{colorMode=button.dataset.mode;localStorage.setItem('badreason-mode',colorMode);applyAppearance();document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===colorMode)));$('#palette-select').innerHTML=(colorMode==='dark'?darkPalettes:palettes).map(([key,label])=>`<option value="${key}" ${key===(colorMode==='dark'?darkPalette:palette)?'selected':''}>${label}</option>`).join('');});$('#full-mode').onclick=()=>{lightMode=false;document.body.classList.remove('low-bandwidth');$('#network-note').hidden=true;sessionStorage.setItem('badreason-full-mode','1');};
