$('#search-toggle').onclick=()=>{$('#search-form').hidden=!$('#search-form').hidden;if(!$('#search-form').hidden){const current=new URL(location.href);$('#search').value=current.pathname==='/buscar'?current.searchParams.get('q')||'':'';$('#search').focus();}};$('#search-close').onclick=()=>$('#search-form').hidden=true;$('#search-form').onsubmit=e=>{e.preventDefault();const query=$('#search').value.trim();$('#search-form').hidden=true;navigate('/buscar?q='+encodeURIComponent(query)+'&limit='+(lightMode?8:12));};
$('#assistant-toggle').onclick=()=>{const panel=$('.assistant-panel');panel.hidden=!panel.hidden;$('#assistant-toggle').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)$('#chat-input').focus();};$('#assistant-close').onclick=()=>{$('.assistant-panel').hidden=true;$('#assistant-toggle').setAttribute('aria-expanded','false');};const botAnswer=(q)=>{const v=q.toLowerCase();if(/precio|price|preço|prix|preis|talla|size|taille|größe|clp/.test(v))return tr('botPrices');if(/env[ií]o|despacho|shipping|order|pedido|compra|delivery|entrega|commande|versand|liefer/.test(v))return tr('botShipping');if(/categor|modelo|model|sneaker|marca|brand|marque|marke/.test(v))return tr('botCatalog');return tr('botFallback');};function reply(text,question=text){const log=$('#chat-log'),user=document.createElement('p'),answer=document.createElement('p');user.className='chat-bubble user-message';user.textContent=question;answer.className='chat-bubble bot-message';answer.textContent=text;log.append(user,answer);log.scrollTop=log.scrollHeight;}document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>reply(tr(`bot${b.dataset.question[0].toUpperCase()+b.dataset.question.slice(1)}`),b.textContent));$('#chat-form').onsubmit=e=>{e.preventDefault();const v=$('#chat-input').value.trim();if(!v)return;reply(botAnswer(v),v);$('#chat-input').value='';};
