history.scrollRestoration='manual';function scrollTop(){window.scrollTo({top:0,left:0,behavior:'auto'});requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'auto'}));}
function navigate(url){history.pushState({},'',url);menu(false);scrollTop();route();}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();navigate(a.pathname+a.search);}});window.onpopstate=()=>{scrollTop();route();};
function cards(list){return list.map((p,i)=>`<article class="product-card" style="--row:${Math.floor(i/4)}"><a href="/producto/${encodeURIComponent(p.id)}"><div class="product-image"><span class="tag">G5 SELECTION</span><img loading="lazy" decoding="async" src="${esc(p.image)}" alt="${esc(p.name)}"><span class="view">${tr('see')} ${icon('arrow')}</span></div><div class="product-caption"><div><small>G5 SELECTION / SNEAKERS</small><h3>${esc(p.name)}</h3></div><span>${money(p.price)}</span></div></a></article>`).join('');}
function crumb(text){return `<div class="breadcrumb"><a href="/">${tr('home')}</a> / ${esc(text)}</div>`;}
function sourceNote(data){return data.source==='snapshot'?`<div class="source-note">${locale==='en'?'G5 reference catalog. Prices and stock are not live.':'Catálogo de referencia de G5 · Precios y stock sin confirmar.'} <button id="retry">${locale==='es'?'Reintentar conexión':tr('next')}</button></div>`:`<div class="source-note live">${tr('origin')}</div>`;}
async function getCatalog(category,page=1,query=''){const started=performance.now();const r=await fetch(query?`/api/search?q=${encodeURIComponent(query)}&page=${page}`:`/api/catalog?category=${encodeURIComponent(category)}&page=${page}`);if(!r.ok)throw Error();const data=await r.json();if(performance.now()-started>2200)activateLightMode();return data;}
function listing(data,title,query='',page=1,limit=12,offset=0){const sourceList=data.source==='live'?data.products:data.products.filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));const total=data.totalCount??(data.source==='live'&&data.pages>1?(data.pages-1)*20+sourceList.length:sourceList.length);const totalPages=Math.max(1,Math.ceil(total/limit));page=Math.min(page,totalPages);const start=(page-1)*limit;const list=data.clientPage?sourceList:data.source==='live'?sourceList.slice(offset,offset+limit):sourceList.slice(start,start+limit);const end=Math.min(total,start+list.length);$('#main').innerHTML=crumb(title)+`<section class="catalog-head"><p class="eyebrow">${tr('catalog')}</p><h1>${esc(title)}<sup>${total}</sup></h1><div class="catalog-toolbar"><span>${tr('show')} ${total?start+1:0}–${end} ${tr('of')} ${total} ${tr('results')}</span><div class="toolbar-controls"><label>${tr('sort')} <select id="sort"><option value="new">${tr('sortNew')}</option><option value="asc">${tr('sortAsc')}</option><option value="desc">${tr('sortDesc')}</option><option value="name">${tr('sortName')}</option></select></label><label>${tr('show')} <select id="limit" aria-label="${tr('show')} ${tr('results')}">${[8,12,20].map(n=>`<option value="${n}" ${n===limit?'selected':''}>${n}</option>`).join('')}</select> ${tr('results')}</label></div></div></section>${sourceNote(data)}<div class="catalog-layout"><aside><h3>${tr('categories')}</h3>${roots.map(([n,p])=>`<a href="/catalogo?category=${encodeURIComponent(p)}">${n} ${icon('arrow')}</a>`).join('')}<a href="/categorias">${tr('allCategories')} ${icon('arrow')}</a><p>Precios en CLP.<br>Elige un producto para consultar tallas y disponibilidad.</p></aside><section><div class="product-grid" id="products">${cards(list)}</div>${!list.length?`<div class="empty"><h2>${tr('noResults')}</h2><p>${tr('trySearch')}</p></div>`:''}<div class="pagination">${page>1?`<button id="prev">${icon('arrow','icon-left')} ${tr('previous')}</button>`:''}<span>${tr('page')} ${page} / ${totalPages}</span>${page<totalPages?`<button id="next">${tr('next')} ${icon('arrow')}</button>`:''}</div></section></div>`;$('#sort').onchange=e=>{const sorted=[...list];if(e.target.value==='asc')sorted.sort((a,b)=>a.price-b.price);if(e.target.value==='desc')sorted.sort((a,b)=>b.price-a.price);if(e.target.value==='name')sorted.sort((a,b)=>a.name.localeCompare(b.name));$('#products').innerHTML=cards(sorted);};$('#limit').onchange=e=>{const u=new URL(location.href);u.searchParams.set('limit',e.target.value);u.searchParams.set('page','1');navigate(u.pathname+u.search);};if($('#retry'))$('#retry').onclick=route;for(const [id,n] of [['prev',page-1],['next',page+1]])if($('#'+id))$('#'+id).onclick=()=>{const u=new URL(location.href);u.searchParams.set('page',n);navigate(u.pathname+u.search);};scrollTop();}
async function route(){stopHeroCarousel();const token=++request;activeProduct=null;const u=new URL(location.href);const path=u.pathname;document.title='BADREASON — Sneakers & culture';
if(path==='/'){$('#main').innerHTML='<div class="loading">BADREASON</div>';let homeData=snapshot;try{homeData=await getCatalog(snapshot.category);}catch{}if(token!==request)return;products=homeData.products;const p=products[0];$('#main').innerHTML=`<section class="hero"><div class="hero-copy">${heroCopy(heroSlides[0])}</div>${heroArtwork()}<div class="hero-index"><span id="hero-position">01 / ${String(heroSlides.length).padStart(2,'0')}</span><span id="hero-model">${esc(heroSlides[0].brand)} / ${esc(heroSlides[0].model)}</span></div></section><div class="ticker">WEAR YOUR REASONS. ✳ BADREASON. ✳ WEAR YOUR REASONS. ✳ BADREASON. ✳</div><section class="featured"><div class="section-title"><div><p class="eyebrow">${tr('catalog')}</p><h2>${locale==='es'?'EL PRÓXIMO DROP.':'YOUR NEXT DROP.'}</h2></div><a href="/catalogo">${tr('allCategories')} ${icon('arrow')}</a></div><div class="product-grid">${cards(products.slice(0,4))}</div><p class="reference-caption">${tr('origin')}</p></section><section class="featured bestsellers" id="bestsellers" aria-labelledby="bestsellers-title"><div class="section-title"><div><p class="eyebrow">G5 / BEST SELLERS</p><h2 id="bestsellers-title">${bestsellerText().title}</h2></div><a href="https://www.g5sneaker.ru/shop/?g5sn_catalog=best&orderby=popularity" target="_blank" rel="noopener noreferrer">${bestsellerText().view} ${icon('arrow')}</a></div><p class="reference-caption">${bestsellerText().source}</p><div id="bestseller-products" class="product-grid" aria-live="polite" aria-busy="true"><p class="bestseller-message">${bestsellerText().loading}</p></div></section><section class="manifesto"><p>${tr('manifesto')}</p><h2>${tr('manifestoTitle')}</h2><a class="button" href="/categorias">${tr('allCategories')} ${icon('arrow')}</a></section>`;loadBestsellers(token);startHeroCarousel(token);scrollTop();return;}
if(path==='/catalogo'||path==='/buscar'){const category=u.searchParams.get('category')||snapshot.category;const limit=Math.max(8,Math.min(20,Number(u.searchParams.get('limit'))||(lightMode?8:12)));const page=Math.max(1,Number(u.searchParams.get('page'))||1);const start=(page-1)*limit;const serverPage=Math.floor(start/20)+1;const lastServerPage=Math.floor((start+limit-1)/20)+1;const offset=start%20;const query=u.searchParams.get('q')||'';const title=path==='/buscar'?`${locale==='es'?'Resultados':locale==='pt'?'Resultados':locale==='fr'?'Résultats':locale==='de'?'Ergebnisse':'Results'}: ${query}`:(categories.find(c=>c.path===category)?.name||tr('sneakers'));$('#main').innerHTML=crumb(title)+`<div class="loading">${tr('catalog')}</div>`;try{let data=await getCatalog(category,serverPage,query);if(token!==request)return;if(data.source==='live'&&lastServerPage>serverPage){const totalCount=data.pages>1?(data.pages-1)*20+20:data.products.length;const next=await getCatalog(category,lastServerPage,query);if(token!==request)return;data={...data,products:[...data.products.slice(offset),...next.products.slice(0,(start+limit)%20)],totalCount,clientPage:true};}products=data.products;listing(data,title,query,page,limit,data.clientPage?0:offset);}catch{if(token!==request)return;if(category===snapshot.category&&page===1)listing(snapshot,title,query,1,limit,0);else $('#main').innerHTML=crumb(title)+`<div class="empty"><h1>${locale==='es'?'No pudimos cargar esta categoría':'We could not load this category'}</h1><p>${locale==='es'?'G5 no está respondiendo. Inténtalo nuevamente.':'G5 is not responding. Please try again.'}</p><button class="button" id="retry">${tr('next')}</button><a href="/catalogo">${tr('sneakers')} ${icon('arrow')}</a></div>`;if($('#retry'))$('#retry').onclick=route;}return;}
if(path.startsWith('/producto/')){const id=decodeURIComponent(path.split('/')[2]||'');$('#main').innerHTML='<div class="loading">CONSULTANDO PRODUCTO…</div>';let p;try{const r=await fetch('/api/product/'+encodeURIComponent(id));if(!r.ok)throw Error();p=await r.json();}catch{p=[...products,...snapshot.products].find(p=>p.id===id);if(p)p={...p,source:'snapshot',images:[p.image],options:[]};}if(token!==request)return;if(!p){$('#main').innerHTML=`<div class="empty"><h1>Producto no disponible</h1><a href="/catalogo">Volver al catálogo ${icon('arrow')}</a></div>`;return;}activeProduct=p;productPage(p);return;}
if(path==='/carrito'){cartPage();return;}
if(path==='/pago'){await checkoutPage();return;}
if(path==='/categorias'){categoryDirectory();return;}
if(path.startsWith('/coleccion/')){await collectionPage(path.split('/')[2],u.searchParams.get('kind')||'shoes',Number(u.searchParams.get('page'))||1,token);return;}
if(path==='/ayuda'||path==='/informacion'){$('#main').innerHTML=crumb('Información')+`<section class="info"><p class="eyebrow">BADREASON / INFORMACIÓN</p><h1>${path==='/ayuda'?'¿TE AYUDAMOS?':'ANTES DE ELEGIR TU PAR.'}</h1><details open><summary>Precios y moneda</summary><p>Los precios se muestran en pesos chilenos (CLP), convertidos desde USD con el dólar observado y un incremento del 30%. No incluyen costos de despacho, impuestos o importación.</p></details><details><summary>Disponibilidad y tallas</summary><p>Consulta cada ficha para cargar las opciones publicadas por G5. Si el proveedor no responde, la vista de referencia no permite agregar productos al carrito.</p></details><details><summary>Compras y despacho</summary><p>El carrito guarda tu selección en este dispositivo. Abre el pago seguro para revisar los métodos habilitados y el total confirmado. La descarga solo exporta tu selección. El despacho se coordina con el comercio.</p></details><details><summary>Privacidad</summary><p>La selección del carrito se guarda localmente en tu navegador. No se reciben números de tarjeta ni CVV. Las órdenes y referencias de pago se guardan en el servidor al iniciar el checkout.</p></details></section>`;return;}
$('#main').innerHTML=`<section class="empty"><h1>404 / FUERA DE ROTACIÓN.</h1><a class="button" href="/">Volver al inicio ${icon('arrow')}</a></section>`;}
function productPage(p){document.title=p.name+' | BADREASON';const live=p.source!=='snapshot';$('#main').innerHTML=crumb(p.name)+`<section class="product-detail"><div class="gallery"><div class="main-image"><img id="detail-image" src="${esc(p.image)}" alt="${esc(p.name)}"></div><div class="thumbnails">${(p.images||[p.image]).map((im,i)=>`<button data-image="${esc(im)}" aria-label="Ver imagen ${i+1}"><img src="${esc(im)}" alt=""></button>`).join('')}</div></div><div class="detail-copy"><p class="eyebrow">G5 SELECTION / SNEAKERS</p><h1>${esc(p.name)}</h1><small>ID ${esc(p.id)}</small><p class="detail-price">${money(p.price)}</p>${!live?'<p class="source-note">Catálogo de referencia. Tallas, stock y precio actual sin confirmar.</p>':''}<p class="description">${esc(p.description||'Consulta las características y disponibilidad de este modelo en el catálogo G5.')}</p><form id="add-form">${(p.options||[]).map((o,i)=>`<label class="option">${esc(/size/i.test(o.label)?'Elige tu talla':o.label)}<select name="option-${i}" required><option value="">Selecciona una opción</option>${o.values.map(v=>`<option value="${esc(v.value)}">${esc(v.label)}</option>`).join('')}</select></label>`).join('')}<label class="option">Cantidad<input type="number" id="qty" min="1" max="10" value="1" required></label><button class="button add" ${!live||p.inStock===false?'disabled':''}>${!live?'DISPONIBILIDAD SIN CONFIRMAR':p.inStock===false?'SIN STOCK':'AGREGAR AL CARRO'} <span>+</span></button></form><div class="delivery"><span>${icon('arrow')}</span><div><b>Tu siguiente par, a un paso.</b><p>Revisa métodos y costo de despacho en el checkout.</p></div></div><details open><summary>Detalles del producto</summary><p>${esc(p.description||p.name)}</p><p>Precio en CLP. Incluye el incremento del 30% sobre G5.</p></details><details><summary>Guía de tallas</summary><p>Selecciona entre las tallas publicadas por el proveedor. Las equivalencias pueden variar entre modelos.</p></details><a class="supplier" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Consultar ficha original en G5 ${icon('arrow')}</a></div></section><section class="featured"><div class="section-title"><h2>TAMBIÉN EN TU ROTACIÓN.</h2><a href="/catalogo">Ver catálogo ${icon('arrow')}</a></div><div class="product-grid">${cards(snapshot.products.filter(x=>x.id!==p.id).slice(0,4))}</div></section>`;document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>$('#detail-image').src=b.dataset.image);$('#add-form').onsubmit=e=>{e.preventDefault();if(!live||p.inStock===false)return;const qty=Number($('#qty').value);if(!Number.isInteger(qty)||qty<1||qty>10)return;const opts=[...new FormData(e.target).entries()].map(([k,v])=>v);const key=p.id+JSON.stringify(opts);const found=cart.find(c=>c.key===key);if(found)found.qty=Math.min(10,found.qty+qty);else cart.push({key,id:p.id,name:p.name,image:p.image,price:p.price,priceUsd:p.priceUsd,currency:'CLP',exchangeRate:p.exchangeRate?.rate||p.exchangeRate,options:opts,qty});updateCart();toast('Agregado a tu rotación.');};}
function cartPage(){const total=cart.reduce((s,c)=>s+c.qty*c.price,0);$('#main').innerHTML=crumb('Carrito')+`<section class="cart-page"><p class="eyebrow">YOUR NEXT ROTATION</p><h1>TU CARRO.</h1>${!cart.length?`<div class="empty"><h2>Todavía no hay pares aquí.</h2><a class="button" href="/catalogo">Explorar sneakers ${icon('arrow')}</a></div>`:`<div class="cart-layout"><div>${cart.map((c,i)=>`<article class="cart-item"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><a href="/producto/${encodeURIComponent(c.id)}">${esc(c.name)}</a><p>${esc(c.options.join(' / '))}</p><label>Cantidad <input data-qty="${i}" type="number" min="1" max="10" value="${c.qty}"></label><button data-remove="${i}">Eliminar</button></div><b>${money(c.price*c.qty)}</b></article>`).join('')}</div><aside class="cart-summary"><h2>Tu selección</h2><p>Subtotal <b>${money(total)}</b></p><p>Despacho e impuestos por confirmar.</p><a class="button" href="/pago">IR AL PAGO SEGURO →</a><button class="button" id="export">DESCARGAR SELECCIÓN ${icon('arrow')}</button><small>Revisa el total y los métodos disponibles antes de pagar. La descarga solo exporta tu selección.</small></aside></div>`}</section>`;document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);updateCart();cartPage();});document.querySelectorAll('[data-qty]').forEach(b=>b.onchange=()=>{cart[Number(b.dataset.qty)].qty=Math.min(10,Math.max(1,Math.floor(Number(b.value)||1)));updateCart();cartPage();});if($('#export'))$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({brand:'Badreason',currency:'CLP',items:cart,total,status:'seleccion-sin-pedido'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='badreason-seleccion.json';a.click();URL.revokeObjectURL(url);};}
route();

async function paymentApi(path,body){const r=await fetch('/api/payments/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo completar la operación.');return data;}
async function checkoutPage(){
 document.title='Pago seguro | BADREASON';
 $('#main').innerHTML=crumb('Pago seguro')+`<section class="payment-page"><div class="payment-heading"><p class="eyebrow">BADREASON / CHECKOUT</p><h1>TU PRÓXIMO<br>PAR EMPIEZA AQUÍ<span>.</span></h1><p>Elige cómo pagar. Tus datos de tarjeta se ingresan en el proveedor de pagos.</p></div><div class="payment-layout"><div><div id="payment-status" class="payment-notice" role="status" aria-live="polite">Consultando métodos disponibles…</div><div id="payment-methods"></div><div class="payment-trust">↗ CONEXIÓN DIRECTA CON EL PROVEEDOR<br>Badreason nunca solicita tu CVV ni contraseña bancaria.</div></div><aside class="payment-summary"><p class="eyebrow">TU SELECCIÓN</p><h2>La próxima rotación.</h2><div id="payment-items">${cart.length?cart.map(i=>`<div class="payment-line"><span>${esc(i.name)}<small>${esc(i.options.join(' / '))} · ${i.qty} unidad(es)</small></span><b>${money(i.price*i.qty)}</b></div>`).join(''):'<p>Tu carrito está vacío.</p>'}</div><div id="payment-total"></div><a href="/carrito">← Volver al carrito</a><p class="payment-fine">El precio y la disponibilidad se vuelven a consultar antes del pago. PayPal cobra en USD; mostrará su conversión cuando corresponda.</p></aside></div><details class="payment-help"><summary>¿Qué falta para activar los pagos?</summary><p>El comercio debe configurar sus credenciales privadas y el costo final del despacho. Las comisiones y los requisitos dependen del proveedor y del país. Google Pay y Apple Pay requieren un procesador y una cuenta compatibles.</p></details></section>`;
 const status=$('#payment-status');
 try{
  const params=new URLSearchParams(location.search);
  if(params.has('cancel')){status.textContent='Pago cancelado. Puedes volver a intentarlo.';return;}
  if(params.has('return')){
   const token=sessionStorage.getItem('badreason-payment');if(!token)throw Error('No encontramos la sesión de esta compra. Revisa el pago en tu cuenta antes de repetirlo.');
   status.textContent='Verificando el pago directamente con el proveedor…';const result=await paymentApi('confirm',{token,paymentId:params.get('payment_id')});
   status.textContent=result.status==='paid'?`Pago verificado por el proveedor. Referencia: ${result.reference}. Comprobante: ${result.receipt}. Conserva estos datos; el despacho se coordina con el comercio.`:'El pago sigue pendiente. Todavía no está confirmado.';
   if(result.status==='paid'){sessionStorage.setItem('badreason-last-receipt',JSON.stringify(result));sessionStorage.removeItem('badreason-payment');}return;
  }
  const config=await paymentApi('config');
  status.textContent=config.mode==='sandbox'?'ENTORNO DE PRUEBAS · Las integraciones configuradas usarán cuentas de prueba.':'ENTORNO REAL · Revisa el importe antes de confirmar.';
  const methods=[['mercadopago','mercado pago','Tarjetas y medios disponibles en tu cuenta.','MP'],['paypal','PayPal','Pago en USD con tu cuenta PayPal.','P'],['transfer','Transferencia bancaria','Confirmación manual del comercio.','↗'],['googlepay','Google Pay','Requiere un procesador compatible y habilitación.','G'],['applepay','Apple Pay','Requiere un procesador compatible y habilitación.','●']];
  $('#payment-methods').innerHTML=methods.map(([id,name,description,mark])=>`<button class="payment-method" data-provider="${id}" ${!config[id]||!cart.length?'disabled':''}><span class="payment-mark ${id}">${mark}</span><span><strong>${name}</strong><small>${description}</small><em>${config[id]?'Disponible':'Pendiente de configuración'}</em></span><span>↗</span></button>`).join('');
  if(!['mercadopago','paypal','transfer'].some(id=>config[id]))status.textContent+=' No hay métodos activos todavía. No se realizarán cobros.';
  let quote;
  if(cart.length&&['mercadopago','paypal','transfer'].some(id=>config[id])){quote=await paymentApi('quote',{items:cart.map(({id,qty,options})=>({id,qty,options}))});$('#payment-total').innerHTML=`<p>Despacho <b>${money(quote.quote.shipping)}</b></p><p class="payment-grand">Total verificado <b>${money(quote.quote.total)}</b></p><p>Con PayPal: USD ${esc(quote.quote.usd)}</p>`;}
  document.querySelectorAll('[data-provider]').forEach(button=>button.onclick=async()=>{
   if(!quote)return;document.querySelectorAll('[data-provider]').forEach(b=>b.disabled=true);status.textContent='Preparando el pago seguro…';
   try{const result=await paymentApi('create',{provider:button.dataset.provider,token:quote.token});if(result.redirect){sessionStorage.setItem('badreason-payment',result.token);location.assign(result.redirect);}else{status.textContent=`Transferencia pendiente de revisión manual. Referencia: ${result.reference}. Total: ${money(result.total)}. Datos: ${result.details}. No se considera pagada hasta que el comercio confirme el abono.`;}}catch(e){status.textContent=e.message;document.querySelectorAll('[data-provider]').forEach(b=>b.disabled=!config[b.dataset.provider]);}
  });
 }catch(e){status.textContent=e.message;document.querySelectorAll('[data-provider]').forEach(b=>b.disabled=true);}
}


function bestsellerText(){return ({es:{title:'LOS MÁS VENDIDOS.',view:'Ver colección en G5',source:'Los más vendidos de G5, en su orden de popularidad. Precios en CLP con el 30% aplicado.',loading:'Consultando los más vendidos de G5…',error:'No pudimos consultar los más vendidos de G5 en este momento.',retry:'Reintentar'},en:{title:'BEST SELLERS.',view:'View collection on G5',source:'G5 best sellers, ordered by popularity. CLP prices include the 30% markup.',loading:'Loading G5 best sellers…',error:'G5 best sellers are temporarily unavailable.',retry:'Try again'},pt:{title:'OS MAIS VENDIDOS.',view:'Ver coleção na G5',source:'Mais vendidos da G5 em ordem de popularidade. Preços em CLP com acréscimo de 30%.',loading:'Consultando os mais vendidos da G5…',error:'Não foi possível consultar os mais vendidos da G5.',retry:'Tentar novamente'},fr:{title:'LES MEILLEURES VENTES.',view:'Voir la collection G5',source:'Meilleures ventes G5 par popularité. Prix en CLP avec majoration de 30 %.',loading:'Chargement des meilleures ventes G5…',error:'Les meilleures ventes G5 sont momentanément indisponibles.',retry:'Réessayer'},de:{title:'DIE BESTSELLER.',view:'Kollektion bei G5 ansehen',source:'G5-Bestseller nach Beliebtheit. CLP-Preise mit 30 % Aufschlag.',loading:'G5-Bestseller werden geladen…',error:'G5-Bestseller sind derzeit nicht verfügbar.',retry:'Erneut versuchen'}})[locale]||{title:'BEST SELLERS.',view:'View G5',source:'G5 best sellers',loading:'Loading…',error:'Unavailable',retry:'Retry'};}
async function loadBestsellers(token){const text=bestsellerText();try{const response=await fetch('/api/bestsellers');if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.products)||!data.products.length)throw Error();if(token!==request||!$('#bestseller-products'))return;$('#bestseller-products').innerHTML=cards(data.products.slice(0,8));$('#bestseller-products').setAttribute('aria-busy','false');}catch{if(token!==request||!$('#bestseller-products'))return;$('#bestseller-products').innerHTML=`<div class="bestseller-message"><p>${esc(text.error)}</p><button class="button" id="bestseller-retry">${esc(text.retry)}</button></div>`;$('#bestseller-products').setAttribute('aria-busy','false');$('#bestseller-retry').onclick=()=>{const container=$('#bestseller-products');container.setAttribute('aria-busy','true');container.textContent=text.loading;loadBestsellers(token);};}}
function categoryDirectory(){
 document.title='Categorías | BADREASON';
 $('#main').innerHTML=crumb('Categorías')+`<section class="category-page category-directory"><p class="eyebrow">ENCUENTRA TU ROTACIÓN</p><h1>PRIMERO, TU MUNDO.<br>DESPUÉS, TU ESTILO.</h1><p class="directory-intro">Explora por actividad o por edad. Elige calzado o completa el look con ropa.</p><input id="category-filter" placeholder="Buscar fútbol, kids, modelo…" aria-label="Buscar categoría"><div id="category-links" class="category-groups">${collections.map((g,i)=>`<article class="category-group" data-category-group style="--collection-accent:${g.accent}"><p class="eyebrow">0${i+1} / ${esc(g.description)}</p><h2>${esc(g.name)}</h2><div class="group-actions"><a href="${collectionHref(g)}">Calzado ${icon('arrow')}</a><a href="${collectionHref(g,'clothing')}">Ropa ${icon('arrow')}</a></div><details><summary>Explorar modelos y marcas</summary><div class="group-models">${groupCategories(g).map(c=>`<a data-model-link href="/catalogo?category=${encodeURIComponent(c.path)}">${esc(c.name)} ${icon('arrow')}</a>`).join('')||'<p>Explora el calzado de esta categoría.</p>'}</div></details></article>`).join('')}</div><p class="reference-caption">Selección de categorías de G5. La ropa de cada grupo aparece solo cuando encontramos productos correspondientes en el proveedor.</p></section>`;
 $('#category-filter').oninput=e=>{const query=e.target.value.trim().toLowerCase();document.querySelectorAll('[data-category-group]').forEach(group=>{const name=group.querySelector('h2').textContent.toLowerCase();const match=name.includes(query);const links=[...group.querySelectorAll('[data-model-link]')];links.forEach(link=>link.hidden=!match&&!link.textContent.toLowerCase().includes(query));const hasMatch=links.some(link=>!link.hidden);group.hidden=!match&&!hasMatch;group.querySelector('details').open=!!query&&!match&&hasMatch;});};
}
async function collectionPage(id,kind,page,token){
 const group=collections.find(g=>g.id===id);if(!group||!['shoes','clothing'].includes(kind)){$('#main').innerHTML='<section class="empty"><h1>Categoría no encontrada</h1><a href="/categorias">Explorar categorías</a></section>';return;}
 const title=group.name+' / '+(kind==='clothing'?'Ropa':'Calzado');document.title=title+' | BADREASON';
 $('#main').innerHTML=crumb(title)+`<section class="collection-page"><p class="eyebrow">BADREASON / ${esc(group.name.toUpperCase())}</p><h1>${esc(group.name)}<span> / ${kind==='clothing'?'ROPA':'CALZADO'}</span></h1><div class="collection-kind"><a href="${collectionHref(group)}" ${kind==='shoes'?'aria-current="page"':''}>Calzado</a><a href="${collectionHref(group,'clothing')}" ${kind==='clothing'?'aria-current="page"':''}>Ropa de ${esc(group.name)}</a></div><div id="collection-results" aria-live="polite"><p class="bestseller-message">Consultando esta colección de G5…</p></div></section>`;
 try{const r=await fetch(`/api/collection?group=${encodeURIComponent(id)}&kind=${kind}&page=${page}`);if(!r.ok)throw Error();const data=await r.json();if(token!==request)return;products=data.products;
 $('#collection-results').innerHTML=data.products.length?`<div class="product-grid">${cards(data.products)}</div><div class="pagination">${page>1?`<a href="${collectionHref(group,kind)}&page=${page-1}">← Anterior</a>`:''}<span>Página ${page} / ${data.pages}</span>${page<data.pages?`<a href="${collectionHref(group,kind)}&page=${page+1}">Siguiente →</a>`:''}</div>`:`<div class="collection-empty"><h2>Todavía no hay ${kind==='clothing'?'ropa':'calzado'} de ${esc(group.name)} disponible.</h2><p>No encontramos productos de esta selección en G5. Puedes explorar el calzado o volver a intentarlo más adelante.</p><a class="button" href="${collectionHref(group)}">Ver calzado ${icon('arrow')}</a></div>`;
 }catch{if(token!==request)return;$('#collection-results').innerHTML='<div class="collection-empty"><h2>No pudimos consultar G5.</h2><p>Intenta nuevamente en unos momentos.</p><button class="button" id="collection-retry">Reintentar</button></div>';$('#collection-retry').onclick=route;}
}
function heroCopy(slide){return `<p class="eyebrow" id="hero-eyebrow">${esc(slide.eyebrow)}</p><h1 id="hero-title">${slide.title}</h1><p id="hero-description">${esc(slide.description)}</p><a class="button light" href="/catalogo">${tr('sneakers').toUpperCase()} ${icon('arrow')}</a>`;}
function heroArtwork(){return `<figure class="hero-artwork" role="img" aria-label="Ilustración editorial de ${esc(heroSlides[0].brand)} ${esc(heroSlides[0].model)} ${esc(heroSlides[0].color)}"><span class="hero-artwork-halo" aria-hidden="true"></span><img class="hero-artwork-slide is-active" src="${esc(heroSlides[0].image)}" alt="" width="1254" height="1254" fetchpriority="high" decoding="async"><img class="hero-artwork-slide" alt="" width="1254" height="1254" decoding="async"></figure>`;}
function startHeroCarousel(routeToken){
 const figure=$('.hero-artwork'),copy=$('.hero-copy');if(!figure||heroSlides.length<2)return;
 const images=[...figure.querySelectorAll('img')];let index=0,active=0,timer=null,stopped=false,preload=null;
 const motion=window.matchMedia?.('(prefers-reduced-motion: reduce)');
 const usable=()=>!stopped&&routeToken===request&&figure.isConnected;
 function loadNext(){const next=(index+1)%heroSlides.length;preload=new Image();preload.src=heroSlides[next].image;}
 function schedule(){if(usable()&&!document.hidden&&!motion?.matches)timer=setTimeout(advance,6500);}
 async function advance(){
  timer=null;if(!usable()||document.hidden||motion?.matches)return;
  const next=(index+1)%heroSlides.length,slide=heroSlides[next],target=images[1-active];
  target.src=slide.image;
  try{if(target.decode)await target.decode();}catch{schedule();return;}
  if(!usable())return;
  // Commit the name, copy and active image together after decoding the image.
  $('#hero-eyebrow').textContent=slide.eyebrow;$('#hero-title').innerHTML=slide.title;$('#hero-description').textContent=slide.description;copy.classList.remove('hero-copy-enter');void copy.offsetWidth;copy.classList.add('hero-copy-enter');
  figure.setAttribute('aria-label',`Ilustración editorial de ${slide.brand} ${slide.model} ${slide.color}`);
  images[active].classList.remove('is-active');target.classList.add('is-active');active=1-active;index=next;
  $('#hero-position').textContent=String(index+1).padStart(2,'0')+' / '+String(heroSlides.length).padStart(2,'0');$('#hero-model').textContent=slide.brand+' / '+slide.model;
  loadNext();schedule();
 }
 const onVisibility=()=>{clearTimeout(timer);timer=null;if(!document.hidden)schedule();};
 const onMotion=()=>{clearTimeout(timer);timer=null;schedule();};
 document.addEventListener('visibilitychange',onVisibility);motion?.addEventListener?.('change',onMotion);
 loadNext();schedule();
 stopHeroCarousel=()=>{stopped=true;clearTimeout(timer);preload=null;document.removeEventListener('visibilitychange',onVisibility);motion?.removeEventListener?.('change',onMotion);};
}
